package org.kanger;
import java.util.*;
import org.kanger.ContextWitnessResultTransport.*;

/** Supplied-profile quiescence only. No live-family/model/admission or writer authority. */
final class ContextSignedWitnessStop {
 static final class Receipt {
  final ContextSignedWitnessRounds.Receipt advance;
  final ContextSignedWitnessNextReceiver.Result terminal;
  final Map<Cut,ConstraintTransfer> products;
  final ContextUniversalSignedUnitExchange.Exchange units;
  final ContextUniversalCompoundExchange.Exchange compounds;
  private Receipt(ContextSignedWitnessRounds.Receipt advance,ContextSignedWitnessNextReceiver.Result terminal,Map<Cut,ConstraintTransfer> products,ContextUniversalSignedUnitExchange.Exchange units,ContextUniversalCompoundExchange.Exchange compounds){this.advance=advance;this.terminal=terminal;this.products=Collections.unmodifiableMap(new LinkedHashMap<>(products));this.units=units;this.compounds=compounds;}
 }
 static final class Result {
  final boolean quiescent;final String phase,reason;final Receipt output;
  private Result(boolean quiescent,String phase,String reason,Receipt output){this.quiescent=quiescent;this.phase=phase;this.reason=reason;this.output=output;}
 }
 private static void require(boolean b,String why){if(!b)throw new IllegalStateException(why);}
 private static ContextSignedWitnessRounds.Result advance(ContextSignedWitnessRounds.Receipt receipt,ContextSignedWitnessContinuationScope.Receipt start,int rows,ContextUniversalFrozenBranch.Limits limits,ContextUniversalGroupedLocalRounds.Limits local,int rounds,int work,int capacity){
  ContextSignedWitnessRounds.checkGrouped(receipt,start,rows,limits,local,rounds,work,capacity);ContextSignedWitnessRounds.Result a=receipt.result;require(a.status==ContextSignedWitnessRounds.Status.ADVANCED&&a.output!=null&&!a.history.isEmpty(),"Complete grouped advancement required for stopping");ContextSignedWitnessRounds.Step last=a.history.get(a.history.size()-1);require(last.output==a.output&&last.checks.localLimits==local&&!last.changes.any(),"All FOUR Source-grade inventories must be unchanged");return a;
 }
 static Result run(ContextSignedWitnessRounds.Receipt receipt,ContextSignedWitnessContinuationScope.Receipt start,int rows,ContextUniversalFrozenBranch.Limits limits,ContextUniversalGroupedLocalRounds.Limits local,int rounds,int work,int capacity){
  String phase="unchanged-grouped-advance";
  try{ContextSignedWitnessRounds.Result a=advance(receipt,start,rows,limits,local,rounds,work,capacity);ContextSignedWitnessContinuationScope.Receipt scope=a.output;
   phase="final-barrier-requalification";ContextSignedWitnessNextReceiver.Result terminal=ContextSignedWitnessNextReceiver.runGrouped(scope,rows,limits,local,work,capacity);require(terminal.status==ContextSignedWitnessNextReceiver.Status.CHECKED,terminal.phase+": "+terminal.reason);
   phase="all-terminal-products";Map<Cut,ConstraintTransfer> products=new LinkedHashMap<>();for(Map.Entry<Cut,ContextUniversalFrozenConstraints.Result> e:terminal.checks.entrySet()){ConstraintTransfer t=ContextWitnessResultTransport.transferConstraintsCertified(terminal.certificates.get(e.getKey()),limits.factDepth,limits.work);require(t.transferred,t.reason);ContextUniversalSignedProductAudit.Result p=ContextUniversalSignedProductAudit.bind(e.getValue(),t,65536,work);require(p.bound,p.reason);products.put(e.getKey(),t);}
   List<Cut> cuts=new ArrayList<>(terminal.checks.keySet());phase="terminal-carrier-collection";ContextUniversalSignedUnitExchange.Collection u=ContextUniversalSignedUnitExchange.collectWithValidationReuse(scope.seeds.frame.plan.x,scope.current().packet,cuts,terminal.checks,limits.clauses,limits.alternatives,limits.factDepth,limits.work,capacity).collection;require(u.collected,u.reason);ContextUniversalCompoundExchange.Collection c=ContextUniversalCompoundExchange.collectWithValidationReuse(scope.seeds.frame.plan.x,scope.current().packet,cuts,terminal.checks,limits.clauses,limits.alternatives,limits.factDepth,limits.work,capacity).collection;require(c.collected,c.reason);
   Receipt r=new Receipt(receipt,terminal,products,u.output,c.output);phase="direct-stop-audit";check(r,receipt,start,rows,limits,local,rounds,work,capacity);return new Result(true,"supplied-profile-quiescent","Final grouped receivers and all four terminal Source-grade projections unchanged; no live-family/model/admission authority",r);
  }catch(Exception failure){return new Result(false,phase,failure.toString(),null);}
 }
 /** Direct actual terminal graph/projection replay, never calls run or a merge adapter. */
 static void check(Receipt r,ContextSignedWitnessRounds.Receipt expected,ContextSignedWitnessContinuationScope.Receipt start,int rows,ContextUniversalFrozenBranch.Limits limits,ContextUniversalGroupedLocalRounds.Limits local,int rounds,int work,int capacity){
  require(r!=null&&r.advance==expected,"Different actual stopping request");ContextSignedWitnessRounds.Result a=advance(expected,start,rows,limits,local,rounds,work,capacity);ContextSignedWitnessContinuationScope.Receipt scope=a.output;ContextSignedWitnessNextReceiver.Result terminal=r.terminal;require(terminal!=null&&terminal.status==ContextSignedWitnessNextReceiver.Status.CHECKED&&terminal.scope==scope&&terminal.localLimits==local,"Actual FINAL barrier local requalification required");ContextSignedWitnessNextReceiver.checkGrouped(terminal,scope,rows,limits,local,work,capacity);Map<Cut,ContextUniversalFrozenConstraints.Result> prior=a.history.get(a.history.size()-1).checks.checks;
  require(terminal.checks.keySet().equals(prior.keySet())&&r.products.keySet().equals(terminal.checks.keySet()),"Complete final receiver/product cut inventory required");
  for(Cut cut:terminal.checks.keySet()){ContextUniversalFrozenConstraints.Result c=terminal.checks.get(cut);require(ContextUniversalGroupedLocalRounds.sameContents(prior.get(cut),c,ContextGroundProductionRounds.budget(work)),"Final requalification changed clause/Source minima");ConstraintTransfer t=r.products.get(cut);require(t!=null&&t.proof==c&&t.before==scope.current().packet&&t.privateBefore==scope.current().privatePools.get(cut),"Different actual final product owner");ContextSignedWitnessNextReceiver.productOwner(terminal,cut,t);ContextUniversalSignedProductAudit.Result p=ContextUniversalSignedProductAudit.bind(c,t,65536,work);require(p.bound,p.reason);require(!t.commonChanged&&!t.localChanged&&ContextWitnessResultTransport.sameContents(scope.current().packet,t.output,work)&&ContextWitnessResultTransport.sameContents(c.pool==null?scope.current().packet:c.pool.local,t.local,work),"Terminal common/private product inventory still changes");}
  require(r.units!=null&&r.compounds!=null&&r.units.x==scope.seeds.frame.plan.x&&r.compounds.x==scope.seeds.frame.plan.x&&r.units.common==scope.current().packet&&r.compounds.common==scope.current().packet&&r.units.checks.equals(terminal.checks)&&r.compounds.checks.equals(terminal.checks)&&r.units.prior==null&&r.units.barrier==null&&r.compounds.prior==null&&r.compounds.barrier==null,"Fresh terminal carrier owners required, not previous equal-valued carriers");require(r.compounds.maximumClauses==limits.clauses&&r.compounds.maximumAlternatives==limits.alternatives&&r.compounds.maximumDepth==limits.factDepth,"Different final carrier policy");
  Runnable audit=ContextGroundProductionRounds.budget(work);ContextUniversalSignedUnitExchange.check(r.units,scope.seeds.frame.plan.x,scope.current().packet,limits.factDepth,audit);ContextUniversalCompoundExchange.check(r.compounds,scope.seeds.frame.plan.x,scope.current().packet,limits.factDepth,audit);List<Cut> cuts=new ArrayList<>(terminal.checks.keySet());ContextUniversalSignedUnitExchange.Collection u=ContextUniversalSignedUnitExchange.collectWithValidationReuse(scope.seeds.frame.plan.x,scope.current().packet,cuts,terminal.checks,limits.clauses,limits.alternatives,limits.factDepth,limits.work,capacity).collection;ContextUniversalCompoundExchange.Collection c=ContextUniversalCompoundExchange.collectWithValidationReuse(scope.seeds.frame.plan.x,scope.current().packet,cuts,terminal.checks,limits.clauses,limits.alternatives,limits.factDepth,limits.work,capacity).collection;
  require(u.collected&&c.collected&&ContextUniversalSignedUnitExchange.sameContents(u.output,r.units,work)&&ContextUniversalCompoundExchange.sameContents(c.output,r.compounds,work),"Incomplete final carrier inventory");require(ContextUniversalSignedUnitExchange.sameContents(r.units,scope.units(),work)&&ContextUniversalCompoundExchange.sameContents(r.compounds,scope.compounds(),work),"Terminal symbolic/compound Source grades still change");
 }
}
